<script setup>import {money,date} from '../api/client.js';defineProps({booking:Object});defineEmits(['cancel','review','view']);</script><template><article class="ticket-card card"><span class="bus-thumb">🚌</span><div class="ticket-code"><b>{{booking.trip.route}}</b><small>{{date(booking.trip.departureTime)}}</small></div><div><b>{{booking.tickets.map(t=>t.seat).join(', ')}}</b></div><div class="ticket-price"><b>{{money(booking.totalAmount)}}</b><span class="status" :class="booking.status">{{booking.status==='PAID'?'Đã đi':booking.status==='CANCELLED'?'Đã hủy':'Sắp đi'}}</span></div><div class="ticket-actions-inline"><button @click="$emit('view',booking)">Xem vé</button><button v-if="['PAID','PENDING_PAYMENT'].includes(booking.status)" @click="$emit('cancel',booking.code)">Hủy</button><button v-if="booking.status==='PAID'" @click="$emit('review',booking.id)">Đánh giá</button></div></article></template>
